<?php require_once __DIR__.'/../includes/bootstrap.php'; if(current_user()) redirect('/dashboard.php'); $pageTitle='Create account — LinkForge';
if(request_is_post()){verify_csrf();$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??''); if(!$email||strlen($password)<12) flash('error','Use a valid email and a password of at least 12 characters.'); else {try{$s=db()->prepare('INSERT INTO users(email,password_hash) VALUES(?,?)');$s->execute([$email,password_hash($password,PASSWORD_DEFAULT)]);login_user(['id'=>(int)db()->lastInsertId()]);flash('success','Welcome to LinkForge.');redirect('/dashboard.php');}catch(PDOException $e){flash('error','An account with that email already exists.');}}} require __DIR__.'/../includes/header.php'; ?><main class="auth-page"><form class="auth-card" method="post"><p class="eyebrow">GET STARTED</p><h1>Forge your link hub.</h1><?=csrf_field()?><label>Email <input name="email" type="email" autocomplete="email" required value="<?=e($_POST['email']??'')?>"></label><label>Password <input name="password" type="password" autocomplete="new-password" minlength="12" required aria-describedby="password-help"></label><p id="password-help" class="form-note">At least 12 characters.</p><button class="button wide">Create account</button><p>Already a member? <a href="<?=e(base_url())?>/login.php">Log in</a></p></form></main><?php require __DIR__.'/../includes/footer.php'; ?>
